    /// Screen.renderMenuBackground: in a world the translucent dark texture,
    /// otherwise the dirt-like menu texture, tiled at 32 pixels.
    pub fn menu_background(
        batch: &mut HudBatch,
        atlas: &HudAtlas,
        x: f32,
        y: f32,
        w: f32,
        h: f32,
        in_world: bool,
    ) {
        let sprite = if in_world {
            "gui/inworld_menu_background"
        } else {
            "gui/menu_background"
        };
        if atlas.sprites.contains_key(sprite) {
            batch
                .pack_blit(
                    atlas,
                    sprite,
                    [x, y, w, h],
                    [0.0, 0.0],
                    [32.0, 32.0],
                    u32::MAX,
                    |batch| tiled(batch, atlas, sprite, x, y, w, h, 32.0, u32::MAX),
                );
        } else {
            batch.fill(atlas, x, y, w, h, rgba(0, 0, 0, 160));
        }
    }
    #[doc(hidden)]
    pub fn __fnr_install_menu_background() -> bool {
        ::horizon_client_render::ui::__fnr_menu_background(menu_background)
    }
